CREATE TABLE public.care_form_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id),code text NOT NULL,kind text NOT NULL CHECK(kind IN ('consent','aftercare')),template_id uuid REFERENCES public.dossier_templates(id),name text NOT NULL,version integer NOT NULL CHECK(version>0),status text NOT NULL DEFAULT 'concept' CHECK(status IN ('concept','live','archived')),text_nl text NOT NULL DEFAULT '',text_en text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid DEFAULT auth.uid(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid DEFAULT auth.uid(),published_at timestamptz,published_by uuid,UNIQUE(tenant_id,code,version));
GRANT SELECT ON public.care_form_versions TO authenticated; GRANT ALL ON public.care_form_versions TO service_role;
ALTER TABLE public.care_form_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY care_forms_read ON public.care_form_versions FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND public.is_aal2() AND (public.has_permission('forms.manage') OR public.has_permission('patients.medical')));
CREATE UNIQUE INDEX care_forms_one_live ON public.care_form_versions(tenant_id,code) WHERE status='live'; CREATE UNIQUE INDEX care_forms_one_concept ON public.care_form_versions(tenant_id,code) WHERE status='concept';
CREATE TRIGGER care_forms_freeze_tenant BEFORE UPDATE ON public.care_form_versions FOR EACH ROW EXECUTE FUNCTION public.freeze_tenant();
INSERT INTO public.care_form_versions(tenant_id,code,kind,name,version,status,text_nl,published_at) SELECT t.id,e.key,'consent',e.key,1,'live',e.value,now() FROM public.tenants t CROSS JOIN LATERAL jsonb_each_text(CASE WHEN jsonb_typeof(t.legal->'consentForms')='object' THEN t.legal->'consentForms' ELSE '{}'::jsonb END) e WHERE length(trim(e.value))>0;
INSERT INTO public.care_form_versions(tenant_id,code,kind,template_id,name,version,status,text_nl,published_at) SELECT t.tenant_id,'aftercare-'||t.id::text,'aftercare',t.id,t.name,1,'live',v.content->>'aftercare',now() FROM public.dossier_templates t JOIN public.dossier_template_versions v ON v.template_id=t.id AND v.tenant_id=t.tenant_id AND v.status='live' WHERE length(trim(coalesce(v.content->>'aftercare','')))>0;
ALTER TABLE public.consult_notes ADD COLUMN care_form_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE FUNCTION public.capture_care_forms(_tenant uuid,_templates uuid[]) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('consents',coalesce((SELECT jsonb_object_agg(c.kind,jsonb_build_object('text',coalesce(f.text_nl,t.legal->'consentForms'->>c.kind,''),'versionId',f.id)) FROM (SELECT DISTINCT jsonb_array_elements_text(coalesce(v.content->'consentForms','[]'::jsonb)) kind FROM public.dossier_template_versions v WHERE v.tenant_id=_tenant AND v.id=ANY(_templates)) c CROSS JOIN public.tenants t LEFT JOIN public.care_form_versions f ON f.tenant_id=_tenant AND f.code=c.kind AND f.kind='consent' AND f.status='live' WHERE t.id=_tenant),'{}'::jsonb),'aftercare',coalesce((SELECT string_agg(coalesce(f.text_nl,v.content->>'aftercare',''),E'\n\n' ORDER BY v.id) FROM public.dossier_template_versions v LEFT JOIN public.care_form_versions f ON f.tenant_id=_tenant AND f.template_id=v.template_id AND f.kind='aftercare' AND f.status='live' WHERE v.tenant_id=_tenant AND v.id=ANY(_templates)),''),'aftercareVersionIds',coalesce((SELECT jsonb_agg(f.id) FROM public.care_form_versions f JOIN public.dossier_template_versions v ON v.template_id=f.template_id AND v.tenant_id=_tenant WHERE f.tenant_id=_tenant AND f.kind='aftercare' AND f.status='live' AND v.id=ANY(_templates)),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.capture_care_forms(uuid,uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.capture_care_forms(uuid,uuid[]) TO service_role;
UPDATE public.consult_notes SET care_form_snapshot=public.capture_care_forms(tenant_id,template_version_ids) WHERE status IN ('draft','parked');
CREATE FUNCTION public.freeze_consult_care_forms() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.care_form_snapshot=public.capture_care_forms(NEW.tenant_id,NEW.template_version_ids); ELSIF NEW.care_form_snapshot IS DISTINCT FROM OLD.care_form_snapshot THEN RAISE EXCEPTION 'Consultteksten staan vast'; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_freeze_consult_care_forms BEFORE INSERT OR UPDATE ON public.consult_notes FOR EACH ROW EXECUTE FUNCTION public.freeze_consult_care_forms();
ALTER TABLE public.patient_consents ADD COLUMN care_form_version_id uuid REFERENCES public.care_form_versions(id);
CREATE FUNCTION public.manage_care_form(_action text,_id uuid DEFAULT NULL,_code text DEFAULT NULL,_kind text DEFAULT NULL,_template uuid DEFAULT NULL,_name text DEFAULT NULL,_nl text DEFAULT NULL,_en text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.care_form_versions; result uuid; tid uuid:=public.current_tenant(); next_version integer; BEGIN
 IF tid IS NULL OR NOT public.is_aal2() OR NOT public.has_permission('forms.manage') THEN RAISE EXCEPTION 'Geen toegang'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(tid::text||'care_forms',0));
 IF _id IS NOT NULL THEN SELECT * INTO r FROM public.care_form_versions WHERE id=_id AND tenant_id=tid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Formulier niet gevonden'; END IF; END IF;
 IF _action='concept' THEN IF _id IS NULL THEN RAISE EXCEPTION 'Formulier niet gevonden'; END IF; SELECT id INTO result FROM public.care_form_versions WHERE tenant_id=tid AND code=r.code AND status='concept'; IF result IS NULL THEN SELECT coalesce(max(version),0)+1 INTO next_version FROM public.care_form_versions WHERE tenant_id=tid AND code=r.code; INSERT INTO public.care_form_versions(tenant_id,code,kind,template_id,name,version,text_nl,text_en) VALUES(tid,r.code,r.kind,r.template_id,r.name,next_version,r.text_nl,r.text_en) RETURNING id INTO result; END IF;
 ELSIF _action='save' THEN IF length(trim(coalesce(_name,'')))=0 OR length(coalesce(_nl,''))>100000 OR length(coalesce(_en,''))>100000 THEN RAISE EXCEPTION 'Controleer de tekst'; END IF; IF _id IS NULL THEN IF length(trim(coalesce(_code,'')))=0 OR coalesce(_kind,'') NOT IN ('consent','aftercare') THEN RAISE EXCEPTION 'Controleer de soort en code'; END IF; IF _template IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.dossier_templates WHERE id=_template AND tenant_id=tid) THEN RAISE EXCEPTION 'Sjabloon niet gevonden'; END IF; INSERT INTO public.care_form_versions(tenant_id,code,kind,template_id,name,version,text_nl,text_en) VALUES(tid,trim(_code),_kind,_template,trim(_name),1,coalesce(_nl,''),coalesce(_en,'')) RETURNING id INTO result; ELSE IF r.status<>'concept' THEN RAISE EXCEPTION 'Maak eerst een concept'; END IF; UPDATE public.care_form_versions SET name=trim(_name),text_nl=coalesce(_nl,''),text_en=coalesce(_en,''),updated_at=now(),updated_by=auth.uid() WHERE id=r.id RETURNING id INTO result; END IF;
 ELSIF _action='publish' THEN IF _id IS NULL OR r.status<>'concept' OR length(trim(r.text_nl))=0 THEN RAISE EXCEPTION 'Vul eerst de Nederlandse tekst in'; END IF; UPDATE public.care_form_versions SET status='archived' WHERE tenant_id=tid AND code=r.code AND status='live'; UPDATE public.care_form_versions SET status='live',published_at=now(),published_by=auth.uid(),updated_at=now(),updated_by=auth.uid() WHERE id=r.id RETURNING id INTO result;
 ELSE RAISE EXCEPTION 'Ongeldige actie'; END IF;
 INSERT INTO public.audit_log(tenant_id,user_id,action,category,record_type,record_id,details) VALUES(tid,auth.uid(),'care_form_'||_action,'settings','care_form_versions',result,jsonb_build_object('description',CASE _action WHEN 'publish' THEN 'Formulier of nazorgtekst live gezet' WHEN 'concept' THEN 'Concept van formulier of nazorgtekst aangemaakt' ELSE 'Formulier of nazorgtekst opgeslagen' END)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.manage_care_form(text,uuid,text,text,uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_care_form(text,uuid,text,text,uuid,text,text,text) TO authenticated;
COMMENT ON COLUMN public.consult_notes.care_form_snapshot IS 'Consent and aftercare text/version snapshot frozen when consult starts; no patient identity. Legacy final consults keep their original template text.';